mdl = 'muxDemo';
new_system(mdl); open_system(mdl);
add_block('simulink/Signal Routing/Mux', [mdl '/Mux']);
set_param([mdl '/Mux'], 'Inputs', '3', 'DisplayOption', 'bar');
add_block('simulink/Sources/Sine Wave', [mdl '/S1']);
add_line(mdl, 'S1/1', 'Mux/1', 'autorouting', 'on');

add_block('simulink/Signal Routing/Bus Selector', [mdl '/BS']);
set_param(mdl, 'SimulationCommand', 'update');
avail = get_param([mdl '/BS'], 'InputSignals');
set_param([mdl '/BS'], 'OutputSignals', 'gyro.x,accel', 'OutputAsBus', 'off');

add_block('simulink/Signal Routing/Vector Concatenate', [mdl '/Cat']);
set_param([mdl '/Cat'], 'NumInputs', '3', 'Mode', 'Vector');
% matrix form:
% set_param([mdl '/Cat'],'Mode','Multidimensional array','ConcatenateDimension','2');

add_block('simulink/Signal Routing/Data Store Read', [mdl '/DSR']);
set_param([mdl '/DSR'], 'DataStoreName', 'CalTable', 'SampleTime', '-1');
add_line(mdl, 'DSR/1', 'Lookup/1', 'autorouting', 'on');

add_block('simulink/Signal Routing/Data Store Write', [mdl '/DSW']);
set_param([mdl '/DSW'], 'DataStoreName', 'CalTable');
add_line(mdl, 'Adapt/1', 'DSW/1', 'autorouting', 'on');

add_block('simulink/Signal Attributes/Data Type Conversion', [mdl '/DTC']);
set_param([mdl '/DTC'], 'OutDataTypeStr', 'fixdt(1,16,7)', ...
    'ConvertRealWorld', 'Real World Value (RWV)', ...
    'RndMeth', 'Nearest', 'SaturateOnIntegerOverflow', 'on');

mdl = 'BusHierarchy';
load_system(mdl);
busInfo = Simulink.Bus.createObject(mdl, [mdl '/Bus Creator1'], 'busDefs', 'object');
% bind the Bus Creator to the generated object
set_param([mdl '/Bus Creator1'], 'OutDataTypeStr', ['Bus: ' busInfo.busName], ...
    'NonVirtualBus', 'on');
% inspect the resulting definition
bo = evalin('base', busInfo.busName);
for k = 1:numel(bo.Elements)
    fprintf('%s : %s\n', bo.Elements(k).Name, bo.Elements(k).DataType);
end
